import sys

def main():
    lines = sys.stdin.read().splitlines()
    if lines:
        line = lines[0]
        res = []
        for ch in line:
            if 'a' <= ch <= 'z':
                break
            res.append(ch)
        print(''.join(res))

if __name__ == '__main__':
    main()

