const fs = require('fs');

function main() {
    const input = fs.readFileSync(0, 'utf-8');
    const line = input.split(/\r?\n/)[0] || '';
    let res = '';
    for (let i = 0; i < line.length; i++) {
        const c = line[i];
        if (c >= 'a' && c <= 'z') break;
        res += c;
    }
    console.log(res);
}

main();

